import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 9
    text = raw_csv.lstrip("\ufeff")

    try:
        records = list(csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False))
    except csv.Error:
        records = []
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False)
        while True:
            try:
                records.append(next(reader))
            except StopIteration:
                break
            except csv.Error:
                continue

    records = [row for row in records if any(value.strip() for value in row)]
    if not records:
        return {"columns": [], "rows": []}

    header_index = None
    header_terms = re.compile(
        r"\b(date|amount|supplier|transaction|number|description|type|entity|department|"
        r"code|name|value|category|area|reference|id)\b",
        re.IGNORECASE,
    )
    date_pattern = re.compile(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$")

    for index, row in enumerate(records[:50]):
        if len(row) != expected_width:
            continue
        joined = " ".join(row)
        signals = len(header_terms.findall(joined))
        looks_like_data = any(date_pattern.match(value) for value in row)
        if signals >= 2 and not looks_like_data:
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (index for index, row in enumerate(records) if len(row) == expected_width),
            0,
        )

    def fit_width(row: list[str]) -> list[str]:
        values = list(row)
        if len(values) > expected_width:
            values = values[: expected_width - 1] + [",".join(values[expected_width - 1 :])]
        elif len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        return values

    columns = fit_width(records[header_index])
    rows = [
        fit_width(row)
        for row in records[header_index + 1 :]
    ]
    return {"columns": columns, "rows": rows}
